-- Additive production migration. Apply through the approved deployment process;
-- do not use drizzle-kit push against production.
--
-- Record IDs are UUIDs generated by Postgres (gen_random_uuid() is built in from
-- PostgreSQL 13). branch_id and pump_id stay text because they reference the
-- existing app_state branch/pump IDs. Amounts are bigint kobo.

CREATE TABLE IF NOT EXISTS payment_terminals (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  provider text NOT NULL,
  provider_terminal_id text NOT NULL,
  branch_id text NOT NULL,
  pump_id text,
  label text NOT NULL,
  status text NOT NULL DEFAULT 'active',
  created_at timestamptz NOT NULL DEFAULT now(),
  disabled_at timestamptz,
  CONSTRAINT payment_terminals_status_check CHECK (status IN ('active', 'disabled')),
  CONSTRAINT payment_terminals_active_requires_pump CHECK (status <> 'active' OR pump_id IS NOT NULL),
  CONSTRAINT payment_terminals_disabled_at_check CHECK ((status = 'active') = (disabled_at IS NULL))
);
CREATE UNIQUE INDEX IF NOT EXISTS payment_terminals_provider_terminal_unique ON payment_terminals(provider, provider_terminal_id);
-- One active terminal per pump; a disabled terminal frees the pump for its replacement.
CREATE UNIQUE INDEX IF NOT EXISTS payment_terminals_active_pump_unique ON payment_terminals(branch_id, pump_id) WHERE status = 'active';
CREATE INDEX IF NOT EXISTS payment_terminals_branch_idx ON payment_terminals(branch_id);

CREATE TABLE IF NOT EXISTS terminal_shift_assignments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  terminal_id uuid NOT NULL REFERENCES payment_terminals(id),
  branch_id text NOT NULL,
  pump_id text,
  attendant_username text NOT NULL,
  opened_at timestamptz NOT NULL,
  closed_at timestamptz,
  opened_by text NOT NULL,
  closed_by text,
  CONSTRAINT terminal_shift_assignments_closed_after_opened CHECK (closed_at IS NULL OR closed_at > opened_at)
);
-- At most one open shift per terminal, so each event maps to a single attendant.
CREATE UNIQUE INDEX IF NOT EXISTS terminal_shift_assignments_open_terminal_unique ON terminal_shift_assignments(terminal_id) WHERE closed_at IS NULL;
CREATE INDEX IF NOT EXISTS terminal_shift_assignments_terminal_time_idx ON terminal_shift_assignments(terminal_id, opened_at);
CREATE INDEX IF NOT EXISTS terminal_shift_assignments_branch_time_idx ON terminal_shift_assignments(branch_id, opened_at);

CREATE TABLE IF NOT EXISTS payment_provider_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  provider text NOT NULL,
  provider_event_id text NOT NULL,
  event_type text NOT NULL,
  payload_sha256 text NOT NULL,
  received_at timestamptz NOT NULL DEFAULT now(),
  occurred_at timestamptz,
  signature_version text NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS payment_provider_events_provider_event_unique ON payment_provider_events(provider, provider_event_id);
CREATE INDEX IF NOT EXISTS payment_provider_events_received_idx ON payment_provider_events(provider, received_at);

CREATE TABLE IF NOT EXISTS payment_transactions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  provider text NOT NULL,
  provider_transaction_id text NOT NULL,
  provider_event_id text NOT NULL,
  provider_event_record_id uuid NOT NULL REFERENCES payment_provider_events(id),
  terminal_id uuid REFERENCES payment_terminals(id),
  shift_assignment_id uuid REFERENCES terminal_shift_assignments(id),
  branch_id text NOT NULL,
  pump_id text,
  method text NOT NULL,
  status text NOT NULL,
  amount_kobo bigint NOT NULL,
  currency text NOT NULL DEFAULT 'NGN',
  occurred_at timestamptz NOT NULL,
  reversal_of_provider_transaction_id text,
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  recorded_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT payment_transactions_amount_positive CHECK (amount_kobo > 0)
);
CREATE UNIQUE INDEX IF NOT EXISTS payment_transactions_provider_tx_unique ON payment_transactions(provider, provider_transaction_id);
CREATE INDEX IF NOT EXISTS payment_transactions_branch_time_idx ON payment_transactions(branch_id, occurred_at);
CREATE INDEX IF NOT EXISTS payment_transactions_terminal_time_idx ON payment_transactions(terminal_id, occurred_at);

CREATE TABLE IF NOT EXISTS payment_ledger_entries (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  transaction_id uuid NOT NULL REFERENCES payment_transactions(id),
  account text NOT NULL,
  direction text NOT NULL,
  amount_kobo bigint NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT payment_ledger_entries_direction_check CHECK (direction IN ('debit', 'credit')),
  CONSTRAINT payment_ledger_entries_amount_positive CHECK (amount_kobo > 0)
);
CREATE INDEX IF NOT EXISTS payment_ledger_entries_transaction_idx ON payment_ledger_entries(transaction_id);
